#!/system/bin/sh
main_func(){ F="$@"; B="${0%/*}/bin/busybox"; base="${F##*/}"; setspan_green "\n  Direct APK Build Verify...\n"; magic="$($B hexdump -n4 -C "$F"|$B head -n1|$B cut -f3,4,5,6 -d ' ')"; [ "$magic" = "50 4b 03 04" ] || ab_ort "Invalid ZIP/APK header."; L="$($B unzip -qql "$F" 2>/dev/null|$B sed 's|.* ||g')"; echo "$L"|$B grep -q '^AndroidManifest.xml$' || ab_ort "AndroidManifest.xml missing."; echo "$L"|$B grep -q '^classes.dex$' || ab_ort "classes.dex missing."; bad="$($B unzip -t "$F" 2>&1 | $B grep -E -i 'error|bad|failed' | $B head -n5)"; if [ -n "$bad" ]; then setspan_red "$bad"; ab_ort "ZIP integrity check failed."; fi; dex=$(echo "$L"|$B grep -E '^classes([0-9]*)?\.dex$'|$B wc -l|$B tr -d ' '); so=$(echo "$L"|$B grep -E '^lib/.+\.so$'|$B wc -l|$B tr -d ' '); abis=$(echo "$L"|$B grep '^lib/'|$B cut -d/ -f2|$B sort -u|$B tr '\n' ' '); sig=$(echo "$L"|$B grep -E '^META-INF/.+\.(RSA|DSA|EC|SF)$'|$B wc -l|$B tr -d ' '); setspan_green "  Container: OK"; echo "  Manifest: OK"; echo "  DEX files: $dex"; echo "  Native libraries: $so"; echo "  ABIs: ${abis:-none}"; echo "  META-INF signing entries: $sig"; setspan_green "\n  Verification complete.\n"; }
[ -f "${0%/*}/bin/utils" ] && . "${0%/*}/bin/utils" || { setspan_red(){ echo "$@"; }; setspan_green(){ echo "$@"; }; setspan_blue(){ echo "$@"; }; }
ab_ort(){ setspan_red "\n  $*\n"; exit 1; }; [ -f "$@" ] || ab_ort "Select an APK file."; main_func "$@"; exit
